CREATE TABLE workstyle_profiles (id text PRIMARY KEY, workspace_id text REFERENCES workspaces(id), agent_id text REFERENCES agents(id) ON DELETE CASCADE, member_id text REFERENCES crm_members(id) ON DELETE CASCADE, enabled boolean NOT NULL DEFAULT false, revision integer NOT NULL DEFAULT 0, preferences jsonb NOT NULL DEFAULT '{}', CHECK ((workspace_id IS NOT NULL AND agent_id IS NOT NULL AND member_id IS NULL) OR (workspace_id IS NULL AND agent_id IS NULL AND member_id IS NOT NULL)), UNIQUE(workspace_id, agent_id), UNIQUE(member_id));
CREATE TABLE workstyle_standards (id text PRIMARY KEY, workspace_id text REFERENCES workspaces(id), brokerage_id text REFERENCES crm_brokerages(id), locked jsonb NOT NULL DEFAULT '{}', requirements jsonb NOT NULL DEFAULT '[]', CHECK ((workspace_id IS NOT NULL) <> (brokerage_id IS NOT NULL)), UNIQUE(workspace_id), UNIQUE(brokerage_id));
CREATE TABLE workstyle_evidence (id text PRIMARY KEY, profile_id text NOT NULL REFERENCES workstyle_profiles(id) ON DELETE CASCADE, source_key text NOT NULL, context_key text NOT NULL, workflow text NOT NULL, before text NOT NULL, after text NOT NULL, signals jsonb NOT NULL, recorded_at timestamptz NOT NULL, fictional boolean NOT NULL);
CREATE UNIQUE INDEX workstyle_evidence_source ON workstyle_evidence(profile_id,source_key);
CREATE TABLE workstyle_suggestions (id text PRIMARY KEY, profile_id text NOT NULL REFERENCES workstyle_profiles(id) ON DELETE CASCADE, rule text NOT NULL, title text NOT NULL, why text NOT NULL, effect text NOT NULL, proposed jsonb NOT NULL, evidence_ids jsonb NOT NULL, supporting integer NOT NULL, considered integer NOT NULL, status text NOT NULL, created_at timestamptz NOT NULL);
CREATE UNIQUE INDEX workstyle_suggestion_rule ON workstyle_suggestions(profile_id,rule);
CREATE TABLE workstyle_changes (id text PRIMARY KEY, profile_id text NOT NULL REFERENCES workstyle_profiles(id) ON DELETE CASCADE, kind text NOT NULL, before jsonb NOT NULL, after jsonb NOT NULL, suggestion_id text, undone boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL);
